using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF 9 renamed the discriminator property from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator" — keep it so they remain readable
            // and raw SQL queries (WHERE c.Discriminator = ...) continue to work.
            entity.HasDiscriminator<string>("Discriminator");

            // EF 9 changed the id format from "EntityType|KeyValue" to just "KeyValue".
            // Existing documents have ids like "Product|123" — preserve that format.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();
        });

        // EF 9 Cosmos provider no longer supports HasIndex — removed.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

